SELECT CASE WHEN YEAR(delivered_date) < 2024 THEN 'before_2024' WHEN YEAR(delivered_date) = 2024 THEN '2024' ELSE 'after_2024' END AS delivered_cohort, COUNT(cost) AS cost_count, ROUND(STDDEV(cost), 2) AS stddev_cost FROM shipments GROUP BY CASE WHEN YEAR(delivered_date) < 2024 THEN 'before_2024' WHEN YEAR(delivered_date) = 2024 THEN '2024' ELSE 'after_2024' END HAVING MIN(cost) >= 79 ORDER BY cost_count DESC
